<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { api, request, type Asset, type Row } from '../api'; import { short, number } from '../utils'; import AsyncPanel from '../components/AsyncPanel.vue'; import StatusBadge from '../components/StatusBadge.vue'; import JsonDetails from '../components/JsonDetails.vue'
const assets=ref<Asset[]>([]), filter=ref(''), selected=ref<Asset|null>(null), detail=ref<Row|null>(null), loading=ref(false), error=ref(''), detailLoading=ref(false), action=ref('')
const providers=computed(()=>[...new Set(assets.value.map(a=>a.provider_id))]); const filtered=computed(()=>assets.value.filter(a=>!filter.value||a.provider_id===filter.value))
async function load() { loading.value=true; error.value=''; try { assets.value=await api.assets(); if(selected.value) await open(assets.value.find(a=>a.asset_id===selected.value!.asset_id&&a.version===selected.value!.version)??selected.value) } catch(e) { error.value=(e as Error).message } finally {loading.value=false} }
async function open(a: Asset) { selected.value=a; detailLoading.value=true; error.value=''; try { detail.value=await api.detail(a) } catch(e) { detail.value=null; error.value=(e as Error).message } finally {detailLoading.value=false} }
async function publish() { action.value=''; try {const r=await request('/publish',{}); action.value=`登记响应：${r.status ?? '已提交'}。仅登记预置的新版本，不生成任务效用。`;await load()} catch(e){error.value=(e as Error).message} }
async function revoke() {if(!selected.value)return; try {await request(`/assets/${encodeURIComponent(selected.value.asset_id)}/status`,{version:selected.value.version,state:'REVOKED'}); action.value='该版本已撤销；新合同和未完成交付由服务端阻断。'; await load()}catch(e){error.value=(e as Error).message}}
const qualityNames:Record<string,string>={completeness:'完整性（1−缺失单元格比例）',uniqueness:'唯一性（1−超额重复行比例）',format_validity:'格式有效性（已填值中规则通过比例）',consistency:'一致性（可检验业务约束通过比例）',quality_score:'四项等权静态质量基线'}
const schema=computed(()=>{const s=detail.value?.asset?.schema??detail.value?.schema??{}; return Array.isArray(s)?s.map((v,i)=>typeof v==='string'?{name:String(i),dtype:v}:v):Object.entries(s).map(([name,dtype])=>({name,dtype:typeof dtype==='object'?JSON.stringify(dtype):dtype}))})
onMounted(load)
</script>
<template><section class="panel"><div class="panel-heading"><div><p class="eyebrow">VERSIONED ASSET CATALOG</p><h2>资产与精确版本</h2></div><div class="actions"><label>提供方<select v-model="filter" aria-label="提供方筛选"><option value="">全部提供方</option><option v-for="p in providers" :key="p">{{ p }}</option></select></label><button class="button" @click="publish">登记预置新版本</button><button class="button secondary" @click="load">刷新</button></div></div><p v-if="action" class="notice" role="status">{{ action }}</p><AsyncPanel :loading="loading" :error="error" @retry="load"><div class="table-wrap"><table><thead><tr><th>资产 / 提供方</th><th>精确版本</th><th>规模</th><th>内容 SHA-256</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="a in filtered" :key="a.asset_id+a.version" :class="{selected:selected?.asset_id===a.asset_id&&selected?.version===a.version}"><td><strong>{{ a.name ?? a.asset_id }}</strong><small>{{ a.asset_id }} · {{ a.provider_id }}</small></td><td class="mono">{{ a.version }}</td><td>{{ a.row_count?.toLocaleString() }} 行<small>{{ a.column_count }} 字段</small></td><td class="mono" :title="a.content_hash">{{ short(a.content_hash,25) }}</td><td><StatusBadge :value="a.state ?? 'VERIFIED_METADATA'"/></td><td><button class="button secondary compact" @click="open(a)">查看详情</button></td></tr><tr v-if="!filtered.length"><td colspan="6" class="empty-cell">没有匹配的资产。请调整筛选或登记预置版本。</td></tr></tbody></table></div></AsyncPanel></section><section v-if="selected" class="panel asset-detail"><div class="panel-heading"><div><p class="eyebrow">ASSET DETAIL / {{ selected.provider_id }}</p><h2>{{ selected.asset_id }}</h2></div><label>切换历史版本<select aria-label="详情版本" :value="selected.version" @change="open(assets.find(a=>a.asset_id===selected!.asset_id&&a.version===($event.target as HTMLSelectElement).value)!)"><option v-for="a in assets.filter(a=>a.asset_id===selected!.asset_id)" :key="a.version">{{ a.version }}</option></select></label></div><AsyncPanel :loading="detailLoading"><template v-if="detail"><div class="notice">元数据签名有效表示登记内容通过签名校验；不能据此声称数据内容 100% 真实或提供方拥有合法产权。</div><dl class="details-grid"><dt>精确版本</dt><dd>{{ selected.version }}</dd><dt>描述</dt><dd>{{ detail.asset?.description ?? selected.description }}</dd><dt>SHA-256</dt><dd class="mono break-word">{{ detail.asset?.content_hash ?? selected.content_hash }}</dd><dt>来源</dt><dd>{{ detail.asset?.provenance?.source ?? detail.asset?.source ?? selected.source ?? '未提供来源' }}</dd><dt>来源署名 / 修改</dt><dd>{{ detail.asset?.provenance?.attribution ?? '未提供署名' }}<small>{{ detail.asset?.provenance?.modifications ?? detail.asset?.provenance?.changes ?? '' }}</small></dd><dt>许可</dt><dd>{{ detail.asset?.license ?? selected.license }}</dd><dt>当前状态</dt><dd><StatusBadge :value="detail.asset?.state ?? selected.state"/></dd><dt>授权策略</dt><dd>{{ detail.asset?.usage_policy ?? detail.asset?.policy ?? detail.policy ?? '未提供策略' }}</dd></dl><div class="two-column"><section><h3>Schema / 格式规则</h3><div class="table-wrap schema-table"><table><thead><tr><th>字段</th><th>类型 / 规则</th></tr></thead><tbody><tr v-for="(s,i) in schema" :key="i"><td class="mono">{{ s.name ?? s.column }}</td><td>{{ s.dtype ?? s.type }}</td></tr></tbody></table></div></section><section><h3>已有数据质量测量</h3><p class="footnote">格式有效不等于事实真实；标签错误可能通过全部格式检查。质量分不用于重复调整价值。</p><template v-if="detail.quality"><p class="muted small">来源：{{ detail.quality.source ?? '保存的质量检测 / 实际文件检查' }}</p><dl class="details-grid"><template v-for="(v,k) in qualityNames" :key="k"><dt>{{ v }}</dt><dd>{{ number(detail.quality[k],4) }}</dd></template></dl><JsonDetails :data="detail.quality" title="质量定义与来源"/></template><p v-else class="notice warning">没有可核验的质量测量；未补造质量分。</p><h3>已有买方任务测量</h3><p>精确匹配资产 ID + 版本 + 内容哈希 + 任务 + 经济场景。</p><JsonDetails :data="detail.task_measurements ?? []" title="任务测量覆盖清单"/><button class="button danger" @click="revoke" :disabled="selected.state==='REVOKED'">撤销此资产版本</button><p class="footnote">研究操作会保存状态事件；不会删除原始资产或冻结结果。</p></section></div><JsonDetails :data="detail" title="完整元数据与来源追踪"/></template></AsyncPanel></section><section v-else class="panel empty-intro"><span>▦</span><h3>选择一份资产，查看它的证据</h3><p>版本、内容哈希、许可与任务测量共同限定评估适用范围。</p></section></template>
